const ar=location.pathname.startsWith('/ar');document.documentElement.lang=ar?'ar':'fr';document.documentElement.dir=ar?'rtl':'ltr';
const t=ar?{title:'الجزرية خطوة بخطوة',sub:'المقدمة الجزرية',chapters:'فهرس الدروس',intro:'افهم المتن وطبّق أحكامه',desc:'اقرأ أبيات ابن الجزري، وتعرّف إلى معانيها، ثم تدرب مع معلم متقن.',units:'١٩ درسًا',langs:'شرح بالعربية',label:'الدرس',verses:'الأبيات',explain:'الشرح الميسّر',exercise:'تدريب وتطبيق',prompt:'اقرأ الأبيات ثلاث مرات. استخرج المصطلحات الأساسية، ثم طبّق القاعدة على ثلاثة أمثلة من المصحف. اعرض قراءتك على معلّم متقن.',checks:['فهمت معنى الأبيات','راجعت المصطلحات','طبقت القاعدة','عرضت قراءتي على معلّم'],prev:'الدرس السابق',next:'الدرس التالي',note:'هذا شرح تمهيدي للكتاب. لا يغني عن التلقي والمشافهة، ويحتاج إلى مراجعة علمية قبل اعتماده للتدريس.',error:'تعذّر تحميل المحتوى. أعد تحميل الصفحة.'}:{title:'La Jazariyya pas à pas',sub:'COMPRENDRE · RÉCITER · PRATIQUER',chapters:'Les chapitres',intro:'Comprendre le poème, pratiquer le tajwīd.',desc:'Retrouvez les vers d’Ibn al-Jazarī, leur explication et un temps de pratique pour chaque chapitre.',units:'19 chapitres',langs:'Édition française',label:'Chapitre',verses:'Vers',explain:'Comprendre',exercise:'Passer à la pratique',prompt:'Lisez les vers trois fois. Relevez les termes essentiels, puis appliquez la règle à trois exemples du muṣḥaf. Présentez votre récitation à un enseignant compétent.',checks:['J’ai compris les vers','J’ai revu les termes','J’ai appliqué la règle','J’ai présenté ma lecture à un enseignant'],prev:'Précédent',next:'Chapitre suivant',note:'Cette adaptation reprend le commentaire introductif du livre. Elle ne remplace pas la transmission orale et reste à relire scientifiquement avant utilisation comme référence pédagogique.',error:'Impossible de charger le contenu. Rechargez la page.'};
const el=(s)=>document.querySelector(s);let data=[];const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.body.innerHTML=`<header><a class="brand" href="${ar?'/ar/':'/fr/'}">${ar?'الجزرية':'La Jazariyya'}<small>${t.sub}</small></a><button class="mobile" aria-expanded="false" aria-controls="chapters">☰ ${t.chapters}</button><a class="lang" href="${ar?'/fr/':'/ar/'}" lang="${ar?'fr':'ar'}">${ar?'Français':'العربية'}</a></header><div class="layout"><aside class="side" id="chapters"><h2>${t.chapters}</h2><nav></nav></aside><main class="main"><section class="intro"><div class="eyebrow">${t.title}</div><h1>${t.intro}</h1><p>${t.desc}</p><div class="meta"><span>${t.units}</span><span>•</span><span>${t.langs}</span></div></section><article class="lesson" id="lesson" aria-live="polite"></article><div class="nav"></div><p class="note">${t.note}</p><footer>${ar?'المقدمة الجزرية بشرح ميسّر':'La Jazariyya expliquée simplement'}</footer></main></div>`;
el('.mobile').onclick=()=>{const open=el('.side').classList.toggle('open');el('.mobile').setAttribute('aria-expanded',open)};
function render(){const id=Number(location.hash.slice(1))||1;const i=Math.max(0,data.findIndex(c=>c.id===id));const c=data[i];document.title=`${c[ar?'ar':'fr']} — ${t.title}`;el('nav').innerHTML=data.map((x,j)=>`<a href="#${x.id}" class="${i===j?'active':''}" ${i===j?'aria-current="page"':''}><span class="num">${String(j+1).padStart(2,'0')}</span>${esc(x[ar?'ar':'fr'])}</a>`).join('');el('#lesson').innerHTML=`<div class="eyebrow">${t.label} ${String(i+1).padStart(2,'0')} · ${t.verses} ${c.id}–${c.end}</div><h2>${esc(c[ar?'ar':'fr'])}</h2>${c.verses.map(v=>`<div class="verse" lang="ar" dir="rtl"><span>${v.n}</span>${esc(v.text)}</div>`).join('')}<h3 class="section-label">${t.explain}</h3><p class="body">${esc(c[ar?'bodyAr':'bodyFr'])}</p><details><summary>${t.exercise}</summary><p class="exercise">${t.prompt}</p><div class="checks">${t.checks.map(x=>`<label><input type="checkbox">${x}</label>`).join('')}</div></details>`;el('.nav').innerHTML=`${i?`<a href="#${data[i-1].id}">${t.prev}</a>`:'<span></span>'}${i<data.length-1?`<a href="#${data[i+1].id}">${t.next}</a>`:''}`;el('.lang').href=(ar?'/fr/':'/ar/')+'#'+c.id;el('.side').classList.remove('open');el('.mobile').setAttribute('aria-expanded','false');}
fetch('/content.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{data=d;render();window.addEventListener('hashchange',()=>{render();el('#lesson').scrollIntoView({block:'start'});});}).catch(()=>el('#lesson').textContent=t.error);
const glossary=document.createElement('details');glossary.className='lesson';glossary.innerHTML=`<summary>${ar?'قاموس المصطلحات':'Glossaire des termes'}</summary><div class="glossary"></div>`;el('.note').before(glossary);fetch('/glossary.json').then(r=>r.json()).then(g=>{el('.glossary').innerHTML=g[ar?'ar':'fr'].map(s=>`<p>${esc(s)}</p>`).join('')}).catch(()=>{el('.glossary').textContent=t.error});
